// 调用次数（ESM 命名空间不支持 `vi.spyOn`；原实现保留、行为零替换）。
// ---------------------------------------------------------------------------

/** proposal.md 文档片段描述符（文档归列按 detail.artifacts[].phase 下标配对）。 */
const PROPOSAL_DESCRIPTOR: ArtifactDescriptor = {
  kind: 'markdown-doc',
