    const { result } = await mounted();

    expect(messageIds(result.current.messages)).toContain('turn-11-user');
    const before = result.current.messages.length;

    deliverEvent(userEvent(9, '补一句'));
    await waitFor(() => {
      expect(messageIds(result.current.messages)).toContain('evt-9');
    });

    const ids = messageIds(result.current.messages);
    expect(result.current.messages.length, '消息数 +1').toBe(before + 1);
    expect(
      ids.filter((id) => id === 'turn-11-user'),
      '提问气泡恒一条',
    ).toHaveLength(1);
    expect(messageTexts(result.current.messages)).toContain('补一句');
    // 位置：提问之后、该轮 assistant 之前
    expect(ids.indexOf('turn-11-user')).toBeLessThan(ids.indexOf('evt-9'));
    expect(ids.indexOf('evt-9')).toBeLessThan(ids.indexOf('turn-11'));
  });

  it('反向判据：turn-<turnId>-user 已在场时再收第二条 user 事件 → 仍追加（不 return、不去重丢弃）', async () => {
    resetIpc({
      detail: summary([turn(11, 'running')]),
      transcript: [userEvent(0, '首轮提问')],
    });
    const { result } = await mounted();
    expect(messageIds(result.current.messages)).toContain('turn-11-user');

    deliverEvent(userEvent(9, '第二条'));
    deliverEvent(userEvent(11, '第三条'));
    await waitFor(() => {
      expect(messageIds(result.current.messages)).toContain('evt-11');
    });

    const ids = messageIds(result.current.messages);
    expect(ids).toContain('evt-9');
    expect(ids).toContain('evt-11');
    expect(ids.filter((id) => id === 'turn-11-user')).toHaveLength(1);
  });

  it('旁观 / 重挂路（无本地副本）：首条 user 事件按提问处理，第二条为补充说明', async () => {
    resetIpc({ detail: summary([turn(11, 'running')]), transcript: [] });
    const { result } = await mounted();
    await waitFor(() => expect(callsOf('agent_session_watch')).toHaveLength(1));

    deliverEvent(userEvent(3, '订阅流首条提问'));
    await waitFor(() => {
      expect(messageIds(result.current.messages)).toContain('turn-11-user');
    });
    deliverEvent(userEvent(9, '订阅流补充说明'));
    await waitFor(() => {
      expect(messageIds(result.current.messages)).toContain('evt-9');
    });

    const ids = messageIds(result.current.messages);
    expect(
      ids.filter((id) => id === 'turn-11-user'),
      '首条归一为提问',
    ).toHaveLength(1);
    expect(ids).toContain('evt-9');
  });

  it('三条补一句：提问 1 条 + 补充说明 2 条，按到达序', async () => {
    resetIpc({ detail: summary([turn(11, 'running')]), transcript: [] });
    const { result } = await mounted();
    await waitFor(() => expect(callsOf('agent_session_watch')).toHaveLength(1));

    deliverEvent(userEvent(3, '提问'));
    deliverEvent(userEvent(9, '补充一'));
    deliverEvent(userEvent(11, '补充二'));
    await waitFor(() => {
      expect(messageIds(result.current.messages)).toContain('evt-11');
    });

    const ids = messageIds(result.current.messages);
    const questions = ids.filter((id) => id === 'turn-11-user');
    const steers = ids.filter((id) => id === 'evt-9' || id === 'evt-11');
    expect(questions).toHaveLength(1);
    expect(steers, '两条补充说明按到达序').toEqual(['evt-9', 'evt-11']);
  });

  it('重投幂等：同一 evt-<seq> 事件重投两次 → 只一条气泡', async () => {
    resetIpc({
      detail: summary([turn(11, 'running')]),
      transcript: [userEvent(0, '首轮提问')],
    });
    const { result } = await mounted();

    deliverEvent(userEvent(9, '重投'));
    deliverEvent(userEvent(9, '重投'));
    await waitFor(() => {
      expect(messageIds(result.current.messages)).toContain('evt-9');
    });
    expect(messageIds(result.current.messages).filter((id) => id === 'evt-9')).toHaveLength(1);
  });

  it('收口同形（AC-10 实时半边）：含补充说明的转录重建为 提问 → 补充说明 → assistant', async () => {
    resetIpc({
      detail: summary([turn(11, 'completed')]),
      transcript: [
        userEvent(3, '首轮提问'),
        textEvent(5, '首轮结论'),
        userEvent(9, '补充说明'),
        textEvent(11, '补充后结论'),
        turnDoneEvent(13),
      ],
    });
    const { result } = await mounted();

    const ids = messageIds(result.current.messages);
    expect(ids).toContain('turn-11-user');
    expect(ids).toContain('evt-9');
    expect(ids.at(-1)).toBe('turn-11');
    expect(ids.indexOf('turn-11-user')).toBeLessThan(ids.indexOf('evt-9'));
    expect(ids.indexOf('evt-9')).toBeLessThan(ids.indexOf('turn-11'));
    expect(messageTexts(result.current.messages)).toContain('补充说明');
  });

  it('turnId = null 旧转录：user 事件走 evt-<seq> 兜底，两两不等（不产生补充说明分支）', async () => {
    resetIpc({
      detail: summary([turn(11, 'completed')], null, SESSION_ID),
      transcript: [
        runStartedEvent(0, null),
        userEvent(1, '旧提问', null),
        textEvent(2, '旧结论', null),
        userEvent(3, '旧补充', null),
        turnDoneEvent(4, null),
      ],
    });
    const { result } = await mounted();

    const ids = messageIds(result.current.messages);
    expect(ids).toContain('evt-1');
    expect(ids).toContain('evt-3');
    expect(new Set(ids).size, 'id 两两不等').toBe(ids.length);
    expect(messageTexts(result.current.messages)).toContain('旧提问');
    expect(messageTexts(result.current.messages)).toContain('旧补充');
  });
});

// ---------------------------------------------------------------------------
// interrupted 轮行的默认行为固化（session-midturn-history-overwrite AC-4 消费面）：
// 生产面零改动——`interrupted` 天然不派生运行中、不触发订阅、重放折叠零特判
// ---------------------------------------------------------------------------

describe('useAgentSession：interrupted 轮行的库态派生', () => {
  it('轮行全 interrupted → running 为 false、零订阅零轮询，loading 回 false', async () => {
    vi.useFakeTimers();
    resetIpc({
      detail: summary([turn(11, 'interrupted')]),
      transcript: [userEvent(0, '中断前提问', 11), textEvent(1, '中断前正文', 11)],
    });
    const { result } = await mounted();

    expect(result.current.running).toBe(false);
    expect(result.current.loading).toBe(false);
    await act(async () => {
      vi.advanceTimersByTime(5 * 60 * 1000);
    });
    expect(callsOf('agent_session_watch')).toHaveLength(0);
  });

  it('轮行 [completed, interrupted] → running 为 false；末条 assistant 的 record 原样透出 interrupted', async () => {
    resetIpc({
      detail: summary([turn(11, 'completed'), turn(13, 'interrupted')]),
      transcript: [
        userEvent(0, '第一问', 11),
        textEvent(1, '第一答', 11),
        userEvent(2, '第二问', 13),
        textEvent(3, '中断前正文', 13),
      ],
    });
    const { result } = await mounted();

    expect(result.current.running).toBe(false);
    const last = result.current.messages.at(-1);
    expect(last?.id).toBe('turn-13');
    expect(last?.metadata?.record?.status).toBe('interrupted');
    expect(messageTexts(result.current.messages)).toContain('中断前正文');
    expect(callsOf('agent_session_watch')).toHaveLength(0);
  });

  it('轮行 [running, interrupted]（残留新轮并存）→ running 仍为 true、恰一次订阅', async () => {
    resetIpc({
      detail: summary([turn(11, 'running'), turn(13, 'interrupted')]),
      transcript: [userEvent(0, '问', 11), textEvent(1, '答', 11)],
    });
    const { result } = await mounted();

    expect(result.current.running).toBe(true);
    await waitFor(() => expect(callsOf('agent_session_watch')).toHaveLength(1));
  });

  it('零轮行（空会话）→ running 为 false、零订阅', async () => {
    resetIpc({ detail: summary([]), transcript: [] });
    const { result } = await mounted();

    expect(result.current.running).toBe(false);
    expect(callsOf('agent_session_watch')).toHaveLength(0);
  });

  it('空内容 interrupted 轮在折叠后仍进 messages（与可见性白名单同口径）', async () => {
    resetIpc({
      detail: summary([turn(11, 'interrupted')]),
      transcript: [
        {
          seq: 0,
          turnId: 11,
          timestampMs: TS,
          kind: 'message',
          role: 'assistant',
          blocks: [],
          parentToolUseId: null,
        },
      ],
    });
    const { result } = await mounted();

    expect(result.current.messages.length).toBeGreaterThan(0);
    expect(result.current.running).toBe(false);
  });
});

// ---------------------------------------------------------------------------
// session-preamble-snapshot：本地轮行镜像与重放装载的快照位（AC-9 / AC-10 前端半边）
// ---------------------------------------------------------------------------

const PREAMBLE = {
  savedAt: TS,
  content: '知识段\n\n<agent_md path="/ws/AGENT.md">\n约定\n</agent_md>\n\n指引',
};

describe('useAgentSession：快照位的镜像与重放', () => {
  it('early-resolve 本地轮行镜像 → preamble 恒 null（轮行无快照面），其余投影不变', async () => {
    resetIpc({ detail: null, transcript: [], start: turn(13, 'running', 'ses-new-p') });
    const { result } = await mounted({ sessionId: null });

    act(() => {
      result.current.sendMessage({ prompt: '开新会话', permissionMode: 'default' });
    });
    await act(async () => {});

    expect(result.current.session?.preamble).toBeNull();
    expect(result.current.session?.row.id).toBe('ses-new-p');
    expect(result.current.session?.stats.turnCount).toBe(1);
    expect(result.current.chain).toEqual([turn(13, 'running', 'ses-new-p')]);
  });

  it('session_detail 返回 null → 会话镜像为 null，无快照读取路径、无异常抛出', async () => {
    resetIpc({ detail: null });
    const { result } = await mounted();

    expect(result.current.session).toBeNull();
    expect(result.current.error).toBeNull();
    expect(result.current.loading).toBe(false);
    expect(callsOf('agent_session_transcript')).toHaveLength(0);
  });

  it('重放装载原样落 preamble（不裁剪、不改写）且 zod 零漂移', async () => {
    resetDrift();
    resetIpc({ detail: summary([turn(11, 'completed')], null, SESSION_ID, PREAMBLE) });
    const { result } = await mounted();

    expect(result.current.session?.preamble).toEqual(PREAMBLE);
    expect(result.current.session?.preamble?.content).toBe(PREAMBLE.content);
    expect(driftCount(), '严格对象 fixture 齐备 ⇒ 零漂移').toBe(0);
  });

  it('返回体 preamble 为 null → 镜像 null（不伪造空对象 / 不填零值）', async () => {
    resetIpc({ detail: summary([turn(11, 'completed')], null, SESSION_ID, null) });
    const { result } = await mounted();

    expect(result.current.session?.preamble).toBeNull();
    expect(result.current.session?.preamble).not.toEqual({ savedAt: 0, content: '' });
  });

  it('超长正文逐字保留（长度守恒），空串正文保留空串 ≠ null', async () => {
    const longContent = `${'中'.repeat(12000)}\n\n🎉 尾段`;
    resetIpc({
      detail: summary([turn(11, 'completed')], null, SESSION_ID, {
        savedAt: TS,
        content: longContent,
      }),
    });
    const long = await mounted();
    expect(long.result.current.session?.preamble?.content).toBe(longContent);
    expect(long.result.current.session?.preamble?.content.length).toBe(longContent.length);

    resetIpc({
      detail: summary([turn(11, 'completed')], null, SESSION_ID, { savedAt: TS, content: '' }),
    });
    const empty = await mounted();
    expect(empty.result.current.session?.preamble?.content).toBe('');
    expect(empty.result.current.session?.preamble?.content).not.toBeNull();
    expect(empty.result.current.session?.preamble).not.toBeNull();
  });

  it('重放后追加轮行（withTurns）→ preamble 不被 stats / turns 现算清空或改写', async () => {
    resetIpc({ detail: summary([turn(11, 'completed')], null, SESSION_ID, PREAMBLE) });
    const { result } = await mounted();
    expect(result.current.session?.preamble).toEqual(PREAMBLE);

    act(() => {
      result.current.sendMessage({ prompt: '续接本轮', permissionMode: 'default' });
    });
    await act(async () => {});

    expect(result.current.session?.stats.turnCount).toBe(2);
    expect(result.current.session?.preamble).toEqual(PREAMBLE);
    expect(result.current.session?.preamble?.savedAt).toBe(PREAMBLE.savedAt);
  });
});

