/** 携 location.state 挂载（autoPrompt 经路由 state 流入详情页）。 */
function renderDetailWithState(
  recordValue: ExploreRecord | null,
  list: ExploreListState,
  state: unknown,
  path = '/explores/api-retry',
) {
  return render(
    <MemoryRouter initialEntries={[{ pathname: path, state }]}>
