}

/** 终态轮行信封载荷（与库内 running 行同 turnId——upsert 原位替换，不叠加行）。 */
function completedTurnRecord(sessionId: string): TurnSummaryLike {
  return {
    turnId: 1,
    sessionId,
    status: 'completed',
    startedAt: 1727000000000,
