      nodeId: 'run:implement:2:executor:0',
    });

    await waitFor(() => expect(screen.getByTestId('detail-drawer') !== null).toBe(true));
    const shell = screen.getByTestId('detail-drawer');
    expect(shell.className).toContain('w-[960px]');
    expect(shell.className).toContain('max-w-[85vw]');
  });

  it('选中面取数失败降级：session_detail reject → 错误态呈现、页脚关闭仍可用、非模态形态不变', async () => {
    const onClose = vi.fn();
    invokeMock.mockImplementation((command: string) =>
      command === 'session_detail' ? Promise.reject('查无此 id') : Promise.resolve(null),
    );
    renderModalLess(
      world([runtimeNode()]),
      { scope: 'node', nodeId: 'run:implement:2:executor:0' },
      { onClose },
    );

    await waitFor(() =>
      expect(screen.getByTestId('detail-drawer').textContent).toContain('查无此 id'),
    );
    expect(drawerViewport().getAttribute('data-modal')).toBe('false');
    expect(overlayNode(), '非模态不因失败退化').toBeNull();

    fireEvent.click(screen.getByRole('button', { name: '关闭' }));
    expect(onClose).toHaveBeenCalledTimes(1);
  });

  it('选中面取数失败降级：read_exec_output reject → 抽屉内错误态不崩、关闭仍可用', async () => {
    const onClose = vi.fn();
    invokeMock.mockImplementation((command: string) =>
      command === 'read_exec_output_delta'
        ? Promise.reject('输出记录读取失败')
        : Promise.resolve(null),
    );
    renderModalLess(
      world([outputNode()]),
      { scope: 'node', nodeId: 'run:implement:2:staticCheck:0' },
      { onClose },
    );

    await waitFor(() => expect(screen.getByTestId('stdout-panel') !== null).toBe(true));
    await waitFor(() =>
      expect(screen.getByTestId('detail-drawer').textContent).toContain('输出记录读取失败'),
    );
    expect(drawerViewport().getAttribute('data-modal')).toBe('false');

    fireEvent.click(screen.getByRole('button', { name: '关闭' }));
    expect(onClose).toHaveBeenCalledTimes(1);
  });
});

// ---------------------------------------------------------------------------
// Esc 监听（`useEffect` 自挂的窗口兜底）：非模态下 base-ui 的 dismiss 不保证
// 触发，故本件在 `window` 上自挂 `keydown`。既有「Esc 关闭」用例经 `document`
// 派发，事件在 base-ui 的 document 监听处即被消费、到不了 `window` 监听器——
// 本节统一在 `window` 上派发，才真正走到自挂监听的判据（EqualityOperator /
// StringLiteral / add-remove 配对 / 选中缺席早返 / 卸载拆除）。
// ---------------------------------------------------------------------------

/** 在 `window` 上派发一次键事件（`target` 恒为 window ⇒ 命中自挂监听）。 */
function pressKeyOnWindow(key: string): void {
  fireEvent.keyDown(window, { key });
}

describe('DetailDrawer：Esc 窗口监听（自挂兜底）', () => {
  it('正向：window 上派发 Escape → onClose 恰 1 次（不经 base-ui dismiss 亦能关闭）', async () => {
    const onClose = vi.fn();
    renderModalLess(world(), { scope: 'column', phase: 'implement' }, { onClose });

    await waitFor(() => expect(screen.getByTestId('detail-drawer') !== null).toBe(true));
    pressKeyOnWindow('Escape');

    expect(onClose).toHaveBeenCalledTimes(1);
  });

  it('异常：非 Escape 键（Enter / 空串 key / 大小写不同）→ onClose 零调用', async () => {
    const onClose = vi.fn();
    renderModalLess(world(), { scope: 'column', phase: 'implement' }, { onClose });

    await waitFor(() => expect(screen.getByTestId('detail-drawer') !== null).toBe(true));
    pressKeyOnWindow('Enter');
    pressKeyOnWindow('');
    pressKeyOnWindow('escape');
    pressKeyOnWindow('Esc');

    expect(onClose).not.toHaveBeenCalled();
  });

  it('异常：selection === null → 不挂监听（window Escape 零调用，抽屉亦不渲染）', () => {
    const onClose = vi.fn();
    const { container } = renderModalLess(world(), null, { onClose });

    pressKeyOnWindow('Escape');

    expect(onClose).not.toHaveBeenCalled();
    expect(container.querySelector('[data-modal]')).toBeNull();
  });

  it('边界：selection 由 null 转非 null → 监听随选中挂上（Esc 生效；选中缺席期不误触发）', async () => {
    const onClose = vi.fn();
    const state = world();
    const { rerender } = renderModalLess(state, null, { onClose });

    pressKeyOnWindow('Escape');
    expect(onClose, '选中缺席期不挂监听').not.toHaveBeenCalled();

    rerender(
      <>
        <DetailDrawer
          selection={{ scope: 'column', phase: 'implement' }}
          graph={state.graph}
          materials={state.materials}
          root={ROOT}
          changeId={CHANGE_ID}
          name={NAME}
          onClose={onClose}
        />
      </>,
    );
    await waitFor(() => expect(screen.getByTestId('detail-drawer') !== null).toBe(true));

    pressKeyOnWindow('Escape');
    expect(onClose).toHaveBeenCalledTimes(1);
  });

  it('边界：选中切换（列头 → 节点）后旧监听已拆 → 单次 Esc 仍只调 onClose 1 次', async () => {
    const onClose = vi.fn();
    const state = world([runtimeNode()]);
    const { rerender } = renderModalLess(
      state,
      { scope: 'column', phase: 'implement' },
      { onClose },
    );
    await waitFor(() => expect(screen.getByTestId('detail-drawer') !== null).toBe(true));

    rerender(
      <>
        <DetailDrawer
          selection={{ scope: 'node', nodeId: 'run:implement:2:executor:0' }}
          graph={state.graph}
          materials={state.materials}
          root={ROOT}
          changeId={CHANGE_ID}
          name={NAME}
          onClose={onClose}
        />
      </>,
    );
    await waitFor(() => expect(screen.getByTestId('session-transcript-panel')).toBeTruthy());

    pressKeyOnWindow('Escape');
    expect(onClose, '旧监听未拆会双触发').toHaveBeenCalledTimes(1);
  });

  it('边界：卸载后 window Escape 零调用（removeEventListener 生效，且退订不残留监听）', async () => {
    const onClose = vi.fn();
    const { unmount } = renderModalLess(
      world(),
      { scope: 'column', phase: 'implement' },
      { onClose },
    );
    await waitFor(() => expect(screen.getByTestId('detail-drawer') !== null).toBe(true));

    unmount();
    pressKeyOnWindow('Escape');

    expect(onClose).not.toHaveBeenCalled();
  });

  it('边界：onClose 身份变化不重复挂监听（同一选中下重渲，Esc 仍只 1 次）', async () => {
    const first = vi.fn();
    const second = vi.fn();
    const state = world();
    const { rerender } = renderModalLess(
      state,
      { scope: 'column', phase: 'implement' },
      { onClose: first },
    );
    await waitFor(() => expect(screen.getByTestId('detail-drawer') !== null).toBe(true));

    rerender(
      <>
        <DetailDrawer
          selection={{ scope: 'column', phase: 'implement' }}
          graph={state.graph}
          materials={state.materials}
          root={ROOT}
          changeId={CHANGE_ID}
          name={NAME}
          onClose={second}
        />
      </>,
    );
    await waitFor(() => expect(screen.getByTestId('detail-drawer') !== null).toBe(true));

    pressKeyOnWindow('Escape');
    // 效果重挂后只有最新回调生效，且恰 1 次（旧引用的监听已拆）
    expect(second).toHaveBeenCalledTimes(1);
    expect(first).not.toHaveBeenCalled();
  });
});

// ---------------------------------------------------------------------------
// ask-tool-in-flow：`askAnswer` 逐层透传至转录面板
// ---------------------------------------------------------------------------

/** ask 工具调用消息（活卡判据面）。 */
function askEvent(seq: number): AgentEvent {
  return {
    seq,
    timestampMs: 1727000000000 + seq,
    kind: 'message',
    role: 'assistant',
    blocks: [
      {
        kind: 'toolUse',
        id: 'call_drawer_1',
        name: 'ask_user_question',
        input: { name: 'q', question: '回溯到哪？', options: ['proposal', 'dev-design'] },
      },
    ],
    parentToolUseId: null,
  };
}

/** 以 askAnswer 渲染 node 范围抽屉。 */
function renderWithAsk(
  worldState: World,
  askAnswer: { onAnswer: (text: string) => void; pendingToolCallId?: string | null } | undefined,
) {
  return render(
    <DetailDrawer
      selection={refreshSelection()}
      graph={worldState.graph}
      materials={worldState.materials}
      root={ROOT}
      changeId={CHANGE_ID}
      name={NAME}
      askAnswer={askAnswer}
      onClose={() => {}}
    />,
  );
}

describe('DetailDrawer：ask 动作面逐层透传（AC-13）', () => {
  it('传 askAnswer（精确 toolCallId）→ 面板活卡提交即回调 onAnswer', async () => {
    detailFixture = {
      [REFRESH_SESSION]: transcriptSession(REFRESH_SESSION, `${CHANGE_ID}/implement/executor/2`),
    };
    transcriptFixture = { [REFRESH_SESSION]: [askEvent(0)] };
    const onAnswer = vi.fn();
    const askAnswer = { onAnswer, pendingToolCallId: 'call_drawer_1' };

    renderWithAsk(world([runtimeNode()]), askAnswer);
    const panel = await screen.findByTestId('session-transcript-panel');
    const buttons = await within(panel).findAllByTestId('ask-answer-option');
    expect(buttons.map((node) => node.textContent)).toEqual(['proposal', 'dev-design']);

    // 探针判据（DD12「同一对象」）：`DetailDrawer` → `DrawerContent` 逐层零加工，
    // 下游收到的就是注入的那一个对象（DOM 与调用次数反推不出引用相等）
    expect(recordedPanelProps().length, '下游应已渲染').toBeGreaterThan(0);
    for (const props of recordedPanelProps()) {
      expect(props.askAnswer).toBe(askAnswer);
      expect(props.askAnswer?.onAnswer).toBe(onAnswer);
    }

    fireEvent.click(buttons[1] as HTMLElement);
    fireEvent.click(within(panel).getByTestId('ask-answer-submit'));
    expect(onAnswer.mock.calls).toEqual([['dev-design']]);
  });

  it('非会话选中对象（scope=column）→ 不渲染会话面板，askAnswer 零消费', async () => {
    const onAnswer = vi.fn();
    render(
      <DetailDrawer
        selection={{ scope: 'column', phase: 'implement' }}
        graph={world([runtimeNode()]).graph}
        materials={world([runtimeNode()]).materials}
        root={ROOT}
        changeId={CHANGE_ID}
        name={NAME}
        askAnswer={{ onAnswer, pendingToolCallId: 'call_drawer_1' }}
        onClose={() => {}}
      />,
    );

    await screen.findByTestId('detail-drawer');
    expect(screen.queryByTestId('session-transcript-panel')).toBeNull();
    expect(screen.queryAllByTestId('ask-answer-option')).toHaveLength(0);
    expect(onAnswer).not.toHaveBeenCalled();
    expect(recordedPanelProps(), '非会话选中对象不挂转录面板').toHaveLength(0);
  });

  it('askAnswer 缺省 → 全静态（零行为变化，既有断言面保持）', async () => {
    detailFixture = {
      [REFRESH_SESSION]: transcriptSession(REFRESH_SESSION, `${CHANGE_ID}/implement/executor/2`),
    };
    transcriptFixture = { [REFRESH_SESSION]: [askEvent(0)] };

    renderWithAsk(world([runtimeNode()]), undefined);
    const panel = await screen.findByTestId('session-transcript-panel');
    await waitFor(() =>
      expect(within(panel).queryAllByTestId('ask-answer-option')).toHaveLength(2),
    );
    expect(within(panel).queryAllByTestId('ask-answer-submit')).toHaveLength(0);
    // 探针判据：缺省即下游每条渲染都收不到动作面
    expect(recordedPanelProps().length).toBeGreaterThan(0);
    for (const props of recordedPanelProps()) expect(props.askAnswer).toBeUndefined();
  });

  it('askAnswer.pendingToolCallId = null → 全静态（历史重放零应答入口）', async () => {
    detailFixture = {
      [REFRESH_SESSION]: transcriptSession(REFRESH_SESSION, `${CHANGE_ID}/implement/executor/2`),
    };
    transcriptFixture = { [REFRESH_SESSION]: [askEvent(0)] };
    const onAnswer = vi.fn();
    const askAnswer = { onAnswer, pendingToolCallId: null };

    renderWithAsk(world([runtimeNode()]), askAnswer);
    const panel = await screen.findByTestId('session-transcript-panel');
    await waitFor(() =>
      expect(within(panel).queryAllByTestId('ask-answer-option')).toHaveLength(2),
    );
    expect(within(panel).queryAllByTestId('ask-answer-submit')).toHaveLength(0);
    expect(onAnswer).not.toHaveBeenCalled();
    // 探针判据：`null` 指针按值直通（对象同一、非重建）
    expect(lastPanelProps().askAnswer).toBe(askAnswer);
    expect(lastPanelProps().askAnswer?.pendingToolCallId).toBeNull();
  });

  it('pendingToolCallId 同链透传：精确 id 注入 → 仅该 id 为活卡（三态矩阵跨两层保持）', async () => {
    detailFixture = {
      [REFRESH_SESSION]: transcriptSession(REFRESH_SESSION, `${CHANGE_ID}/implement/executor/2`),
    };
    // 两条 ask 调用（call_a / call_b），仅 call_b 为当前等待条目
    transcriptFixture = {
      [REFRESH_SESSION]: [
        {
          seq: 0,
          timestampMs: 1727000000000,
          kind: 'message',
          role: 'assistant',
          blocks: [
            {
              kind: 'toolUse',
              id: 'call_a',
              name: 'ask_user_question',
              input: { name: 'q', question: '第一问', options: ['甲', '乙'] },
            },
            {
              kind: 'toolUse',
              id: 'call_b',
              name: 'ask_user_question',
              input: { name: 'q', question: '第二问', options: ['丙', '丁'] },
            },
          ],
          parentToolUseId: null,
        },
      ],
    };
    const onAnswer = vi.fn();
    const askAnswer = { onAnswer, pendingToolCallId: 'call_b' };

    renderWithAsk(world([runtimeNode()]), askAnswer);
    const panel = await screen.findByTestId('session-transcript-panel');
    // 两卡各两条选项行，但提交入口只在 call_b（当前等待条目）卡内
    expect(within(panel).queryAllByTestId('ask-answer-option')).toHaveLength(4);
    expect(within(panel).queryAllByTestId('ask-answer-submit')).toHaveLength(1);
    const liveCard = within(panel)
      .getAllByTestId('ask-question-card')
      .find((card) => within(card).queryAllByTestId('ask-answer-submit').length > 0)!;
    const buttons = within(liveCard).getAllByTestId('ask-answer-option');
    expect(buttons.map((node) => node.textContent)).toEqual(['丙', '丁']);
    // 探针判据：判活指针沿链条原值直通（未被重建为新对象）
    expect(lastPanelProps().askAnswer).toBe(askAnswer);
    expect(lastPanelProps().askAnswer?.pendingToolCallId).toBe('call_b');

    fireEvent.click(buttons[0] as HTMLElement);
    fireEvent.click(within(liveCard).getByTestId('ask-answer-submit'));
    expect(onAnswer.mock.calls).toEqual([['丙']]);
  });
});

