    rerender(
      panelUi({
        state: panelState({
          sessions: [summary('ses-1'), summary('ses-2'), summary('ses-3')],
          total: 2,
          loadMore,
        }),
      }),
    );
    expect(screen.queryByTestId('archi-chat-history-more'), '超量（判据 < 严格）不呈').toBeNull();
  });
});

