  });

  it('轮收口（库态 running → completed）→ 清单再重取一次', async () => {
    ipc.detail = summary([turn(11, 'running', 'ses-1')], 'ses-1');
    const { result } = await mounted();
    act(() => {
      result.current.selectSession('ses-1');
    });
